# Define a function to register a plugin
def register_plugin(plugin_name, plugin_instance):
    global plugins
    if plugin_name not in plugins:
        plugins[plugin_name] = []
    plugins[plugin_name].append(plugin_instance)

# Define a function to call all registered plugins with a given argument
def call_plugins(plugin_name, argument):
    global plugins
    if plugin_name in plugins:
        for plugin in plugins[plugin_name]:
            plugin.execute(argument)

# Define a class to represent a hook system
class HookSystem:
    def __init__(self):
        self.hooks = []

    # Define a method to register a callback function
    def register_callback(self, callback_function):
        self.hooks.append(callback_function)

    # Define a method to execute all registered callbacks with a given argument
    def execute_callbacks(self, argument):
        for callback in self.hooks:
            callback(argument)

# Create an instance of the plugin system
plugins = {}
register_plugin('plugin1', Plugin('Plugin 1'))
register_plugin('plugin2', Plugin('Plugin 2'))

# Create an instance of the hook system
hook_system = HookSystem()
hook_system.register_callback(lambda arg: print(f"Executing hook with argument: {arg}"))

# Call all registered plugins with the argument "Hello"
call_plugins('plugin1', 'Hello')

# Execute all registered hooks with the same argument
hook_system.execute_callbacks('Hello')
```

