import ast
import re

class CyclomaticComplexityChecker(ast.NodeVisitor):
    def __init__(self, max_complexity=10):
        self.max_complexity = max_complexity
        self.complexity_count = 0

    def visit_Comparison(self, node):
        if len(node.ops) > 1:
            self.complexity_count += 1
        super().visit_Comparison(node)

    def visit_If(self, node):
        self.complexity_count += 1
        super().visit_If(node)

    def visit_For(self, node):
        self.complexity_count += 1
        super().visit_For(node)

    def visit_While(self, node):
        self.complexity_count += 1
        super().visit_While(node)

    def visit_Break(self, node):
        pass

    def visit_Continue(self, node):
        pass

def check_cyclomatic_complexity(file_path, max_complexity=10):
    tree = ast.parse(open(file_path).read())
    visitor = CyclomaticComplexityChecker(max_complexity)
    visitor.visit(tree)

    if visitor.complexity_count > max_complexity:
        return True
    else:
        return False

# Example usage
file_path = "example.py"
if check_cyclomatic_complexity(file_path):
    print(f"Cyclomatic complexity exceeds {max_complexity}. Please refactor.")
else:
    print("Cyclomatic complexity is within acceptable limits.")

