# Define a custom regular expression engine class
class CustomRegexEngine:
    def __init__(self):
        # Initialize the engine state
        self.state = {}

    def compile(self, pattern):
        # Compile the regex pattern into a machine representation
        return re.compile(pattern)

    def search(self, compiled_pattern, string):
        # Search for a match in the given string using the compiled pattern
        match = compiled_pattern.search(string)
        if match:
            return match.group()
        return None

    def findall(self, compiled_pattern, string):
        # Find all matches in the given string using the compiled pattern
        return compiled_pattern.findall(string)

    def sub(self, compiled_pattern, replacement, string):
        # Replace all occurrences of the matched pattern in the string
        return compiled_pattern.sub(replacement, string)

    def match(self, compiled_pattern, string):
        # Match the pattern at the beginning of the string
        match = compiled_pattern.match(string)
        if match:
            return match.group()
        return None

    def split(self, compiled_pattern, string):
        # Split the string by matching the pattern
        return compiled_pattern.split(string)

# Example usage of the custom regular expression engine
engine = CustomRegexEngine()

# Compile a regular expression pattern
pattern = r"\b\w+\b"  # Matches words
compiled_pattern = engine.compile(pattern)

# Search for a word in a string
