def singledispatch(func):
    registry = {}

    def register(type_):
        def wrapper(func):
            registry[type_] = func
            return func
        return wrapper

    def dispatch(obj):
        if type(obj) not in registry:
            raise TypeError(f"No handler for type {type(obj)}")
