def calculate_duration(duration_str):
    # Calculate the duration from the given string
    if 'in' in duration_str:
        parts = duration_str.split()
        number = float(parts[0])
        unit = parts[1]
        if unit == 'hours':
            delta = relativedelta(hours=number)
        elif unit == 'days':
            delta = relativedelta(days=number)
        elif unit == 'weeks':
            delta = relativedelta(weeks=number)
        elif unit == 'months':
            delta = relativedelta(months=number)
        else:
            raise ValueError("Unsupported duration unit")
    else:
        raise ValueError("Invalid duration string")
    return delta

def compare_dates(date1, date2):
    # Compare two dates and return True if date1 is before date2
    return date1 < date2

