import datetime
import pytz

# Importing the required modules from the standard library
from typing import List, Tuple, Dict

class TimeZoneInfo:
    def __init__(self, name: str, offset: int, dst_offset: int):
        self.name = name
        self.offset = offset  # In minutes east of UTC
        self.dst_offset = dst_offset  # In minutes east of UTC during daylight saving time

    @classmethod
    def from_tz_info(cls, tz_info: pytz.tzinfo):
        return cls(tz_info.zone_name, tz_info.utcoffset(None), tz_info.dst())

    def convert(self, dt: datetime.datetime) -> datetime.datetime:
        if dt.tzinfo is None:
            raise ValueError("Datetime must have a timezone")

        if dt.tzinfo == pytz.utc:
            return dt + datetime.timedelta(minutes=self.offset)

        local_dt = dt.astimezone(pytz.utc).replace(tzinfo=pytz.utc)
        offset_from_utc = local_dt.utcoffset()
        adjusted_local_dt = local_dt - offset_from_utc

        if self.dst() and (adjusted_local_dt.hour < 0 or adjusted_local_dt.hour >= 23):
            # Adjusting for daylight saving time
            adjusted_local_dt += datetime.timedelta(hours=-1)

        return adjusted_local_dt.replace(tzinfo=self.name)

def get_time_zones() -> List[TimeZoneInfo]:
    all_timezones = pytz.all_timezones
    time_zone_info_list = []
    for tz_name in all_timezones:
        try:
            tz_info = pytz.timezone(tz_name)
            time_zone_info_list.append(TimeZoneInfo.from_tz_info(tz_info))
        except pytz.exceptions.UnknownTimeZoneError:
            continue
    return time_zone_info_list

# Example usage
time_zone_info_list = get_time_zones()
for tz in time_zone_info_list[:5]:  # Display first five time zones
    print(f"Time Zone: {tz.name}")
    print(f"Offset: {tz.offset} minutes east of UTC")
    print(f"Daylight Saving Time Offset: {tz.dst_offset} minutes east of UTC")
```

