class Inflector:
    def __init__(self):
        self.pluralization_rules = {
            "s": lambda word: word + "es",
            "x": lambda word: word + "es" if word.endswith("ix") else word + "ex",
            "z": lambda word: word + "zes" if word.endswith("z") else word + "z"
        }
        self.singularization_rules = {
            "es": lambda word: word[:-2],
            "ex": lambda word: word[:-2] if word.endswith("ex") else word[:-1],
            "zes": lambda word: word[:-3]
        }
        self.camel_case_rules = {
            "_": lambda word: word.replace("_", "")
        }

    def pluralize(self, word):
        if word.endswith('s'):
            return self.pluralization_rules['s'](word)
        elif word.endswith('x') or word.endswith('sh') or word.endswith('ch'):
            return self.pluralization_rules['x'](word)
        elif word.endswith('z'):
            return self.pluralization_rules['z'](word)
        else:
            return word + 's'

    def singularize(self, word):
        if word.endswith('es'):
            return self.singularization_rules['es'](word)
        elif word.endswith('ex'):
            return self.singularization_rules['ex'](word)
        elif word.endswith('zes'):
            return self.singularization_rules['zes'](word)
        else:
            return word

    def camel_case(self, word):
        return self.camel_case_rules['_'](word)

# Example usage
