import numpy as np
from sklearn.metrics.pairwise import cosine_similarity

# Define a function to calculate Levenshtein distance between two strings
def levenshtein_distance(s1, s2):
    n, m = len(s1), len(s2)
    dp = np.zeros((n+1, m+1))

    for i in range(n+1):
        dp[i, 0] = i
    for j in range(m+1):
        dp[0, j] = j

    for i in range(1, n+1):
        for j in range(1, m+1):
            if s1[i-1] == s2[j-1]:
                cost = 0
            else:
                cost = 1
            dp[i, j] = min(dp[i-1, j]+1, dp[i, j-1]+1, dp[i-1, j-1]+cost)

    return dp[n, m]

# Define a function to calculate Jaccard similarity between two sets of words
def jaccard_similarity(set1, set2):
    intersection = set1.intersection(set2)
    union = set1.union(set2)
    return len(intersection) / len(union)

# Define a function to calculate cosine similarity between two vectors
def cosine_similarity(vector1, vector2):
    return np.dot(vector1, vector2) / (np.linalg.norm(vector1) * np.linalg.norm(vector2))

# Function to perform fuzzy string matching using different methods
def fuzzy_string_matching(query, database, method='cosine', threshold=0.6, duplicates=True):
    results = []
    for item in database:
        # Convert strings to sets for comparison
        query_set = set(query.split())
        item_set = set(item.split())

        # Calculate distance based on selected method
        if method == 'levenshtein':
            distance = levenshtein_distance(query, item)
        elif method == 'jaccard':
            distance = jaccard_similarity(query_set, item_set)
        elif method == 'cosine':
            query_vector = np.array([1 if char in query_set else 0 for char in 'abcdefghijklmnopqrstuvwxyz'])
            item_vector = np.array([1 if char in item_set else 0 for char in 'abcdefghijklmnopqrstuvwxyz'])
            distance = cosine_similarity(query_vector, item_vector)
        else:
            raise ValueError("Unsupported method")

        # Check if the distance meets the threshold
        if distance <= threshold:
            result = {
                'query': query,
                'item': item,
                'distance': distance,
                'match_type': 'exact' if distance == 0 else 'partial'
            }
            results.append(result)

    # Handle duplicates by removing them
    if not duplicates:
        unique_results = {result['item']: result for result in results}.values()
        results = list(unique_results)

    return results

# Example usage
queries = ['apple', 'banana', 'cherry']
database = ['applesauce', 'bananas', 'cherries', 'grapes']
matches = fuzzy_string_matching(queries, database, method='cosine', threshold=0.5, duplicates=False)

for match in matches:
    print(f"Query: {match['query']}, Item: {match['item']}, Distance: {match['distance']}")
```

This Python code defines functions to calculate Levenshtein distance, Jaccard similarity, and cosine similarity between two strings or sets of words. It also includes a main function `fuzzy_string_matching` that uses these metrics to find similar items in a database based on a specified method and threshold. The function can handle duplicates by default, but this behavior can be disabled by setting `duplicates=False`. The example usage demonstrates how to use this function with a sample query and database, and prints out the matching items along with their distances.

