class LanguagePreCommit:
    def __init__(self, config_file):
        self.config = self.load_config(config_file)
        self.hooks = {}

    def load_config(self, config_file):
        with open(config_file, 'r') as file:
            return eval(file.read())

    def register_hook(self, language, hook):
        if language not in self.hooks:
            self.hooks[language] = []
        self.hooks[language].append(hook)

    def run_hooks(self, files):
        for language, hooks in self.hooks.items():
            for hook in hooks:
                if callable(hook):
                    hook(files)
                else:
                    raise ValueError(f"Hook {hook} is not callable")

    def add_pre_commit_script(self, script_path, language=None):
        if language:
            self.register_hook(language, script_path)
        else:
            # Assuming a default language is set in the config
            default_language = self.config.get('default_language', None)
            if default_language:
                self.register_hook(default_language, script_path)
            else:
                print("No default language configured")

def main():
    config_file = "precommit_config.json"
    pre_commit = LanguagePreCommit(config_file)

    # Register some sample hooks
    pre_commit.add_pre_commit_script("lint.sh", "Python")
    pre_commit.add_pre_commit_script("format.py", "JavaScript")

    # Add another hook without specifying a language
    pre_commit.add_pre_commit_script("test.sh")

    # Run all registered hooks on some files
    files_to_check = ["main.py", "index.js"]
    pre_commit.run_hooks(files_to_check)

if __name__ == "__main__":
    main()
```

This code defines a `LanguagePreCommit` class that manages pre-commit hooks across different programming languages. It includes methods to load configurations from a JSON file, register hooks for specific languages, run hooks on a list of files, and add scripts as pre-commit hooks. The `main` function demonstrates how to use this class by registering hooks and running them on example files.

